          process.exit(2);
        }
        if (!validMetrics.includes(metric)) {
          log.error(`Unknown metric: ${metric}. Valid metrics are: ${validMetrics.join(', ')}`);
          process.exit(2);
        }
        thresholds[metric] = value;
      }
      return thresholds;
    };

    const result = parseThresholds(['exact_match=0.9', 'toxicity=0.85']);
    expect(result).toEqual({ exact_match: 0.9, toxicity: 0.85 });
